import fs from 'fs';
import path from 'path';
import type { VariantHistoryService } from './VariantHistoryService';
import { createLogger } from '../index-core';
import {
  AgentVariantsOrchestrator,
  SessionStore,
  type ProjectEnvironment,
  type WorktreeManagerLike,
} from '../agent-variants';
import {
  FRAMEWORK_DEV_CONFIG,
  buildDevServerCommand,
  resolveDevScript,
} from '../utils/devServerCommand';
import { ProjectDetectionService } from './ProjectDetectionService';
import { SessionBridgeService } from './SessionBridgeService';
import { TelemetryService } from './TelemetryService';
import { WorktreeManager } from './WorktreeManager';
import { resolveStaticProjectTarget } from './staticProjectTarget';

const log = createLogger('AgentVariantsOrchestratorFactory');

const AGENT_VARIANTS_EVENT_PREFIX = 'agent_variants.';

const VARIANTS_REPLAY_LINKED = Symbol('variantsSessionReplayLinked');

export const withVariantsSessionReplayLinking = (
  telemetry: TelemetryService,
  bridge: SessionBridgeService,
): TelemetryService => {
  if (
    (telemetry as { [VARIANTS_REPLAY_LINKED]?: boolean })[
      VARIANTS_REPLAY_LINKED
    ]
  ) {
    return telemetry;
  }
  return new Proxy(telemetry, {
    get(target, prop, receiver) {
      if (prop === VARIANTS_REPLAY_LINKED) {
        return true;
      }
      if (prop !== 'track') {
        return Reflect.get(target, prop, receiver);
      }
      return (
        event: string,
        properties: Record<string, unknown> = {},
      ): void => {
        if (
          !event.startsWith(AGENT_VARIANTS_EVENT_PREFIX) ||
          properties.$session_id
        ) {
          target.track(event, properties);
          return;
        }
        const context = bridge.getTelemetryContext();
        if (!context?.browserSessionId && !context?.browserDistinctId) {
          target.track(event, properties);
          return;
        }
        target.track(event, {
          ...properties,
          ...(context.browserSessionId
            ? { $session_id: context.browserSessionId }
            : {}),
          ...(context.browserDistinctId && !properties.browser_distinct_id
            ? { browser_distinct_id: context.browserDistinctId }
            : {}),
        });
      };
    },
  });
};

export type CreateAgentVariantsOrchestratorOptions = {
  history?: VariantHistoryService;
  bridge: SessionBridgeService;
  telemetry?: TelemetryService;
  projectPathFallback?: string;
  staticEntry?: string;
  cwd?: () => string;
  worktreeManager?: WorktreeManagerLike;
  resolveProjectEnvironment?: (
    sessionId: string,
  ) => Promise<ProjectEnvironment>;
};

export const createAgentVariantsOrchestrator = (
  options: CreateAgentVariantsOrchestratorOptions,
): AgentVariantsOrchestrator => {
  const cwd = options.cwd ?? (() => process.cwd());
  const getProjectPath = (): string =>
    options.bridge.getProjectPath() ?? options.projectPathFallback ?? cwd();

  const telemetry =
    options.telemetry !== undefined
      ? withVariantsSessionReplayLinking(options.telemetry, options.bridge)
      : undefined;

  return new AgentVariantsOrchestrator({
    getProjectPath,
    store: new SessionStore(),
    variantHistory: options.history,
    worktreeManager:
      options.worktreeManager ?? new WorktreeManager(getProjectPath),
    telemetry,
    resolveProjectEnvironment:
      options.resolveProjectEnvironment ??
      (async (sessionId: string): Promise<ProjectEnvironment> => {
        const projectPath = getProjectPath();
        const detection = new ProjectDetectionService();
        const framework = detection.detectFramework(projectPath);
        if (framework === 'static') {
          const entryPath = resolveStaticProjectTarget({
            targetPath: projectPath,
            entryPath: options.staticEntry,
          }).entryPath;
          const hasEntry =
            options.staticEntry !== undefined ||
            fs.existsSync(path.join(projectPath, entryPath));
          log.info(
            `Resolved env for variants session ${sessionId}: static/${hasEntry ? entryPath : '(no entry page)'}`,
          );
          return {
            projectPath,
            framework,
            ...(hasEntry ? { entryPath } : {}),
          };
        }
        const packageManager =
          await detection.detectPackageManager(projectPath);
        const devCommand = resolveDevScript(projectPath, framework);
        const defaultPort = FRAMEWORK_DEV_CONFIG[framework]?.defaultPort;
        log.info(
          `Resolved env for variants session ${sessionId}: ${framework}/${packageManager}`,
        );
        return {
          projectPath,
          framework,
          packageManager,
          devCommand,
          defaultPort,
          buildDevCommand: (port: number) =>
            buildDevServerCommand(framework, packageManager, devCommand, port),
        };
      }),
    switchPreviewPort: (port) => options.bridge.switchPreviewPort(port),
  });
};
